(7641289, 1240700, 97225, '<td valign="top">Congrats on the HM. Great entry - 9 from me.</td>', 'Congrats on the HM. Great entry - 9 from me.', '2019-09-13 01:24:28.000000', NULL, 0),
(7641310, 1240704, 144365, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roz:</b></div><hr/><i> congratulations on the red .. this is an absolutely amazing image ..  i cant imagine how you do this sort of photography .. blown me away .. :) </i></td></tr></table> <br/> <br/>It''s easy. Water + sugar + soap + glycerine + flash. You just have to make sure the plane of the soap is relatively flat and the flash is pointing in the right direction. After that it''s a liberal use of editing.</td>', 'Originally posted by roz: congratulations on the red .. this is an absolutely amazing image ..  i cant imagine how you do this sort of photography .. blown me away .. :)   It''s easy. Water + sugar + soap + glycerine + flash. You just have to make sure the plane of the soap is relatively flat and the flash is pointing in the right direction. After that it''s a liberal use of editing.', '2019-09-13 02:39:05.000000', NULL, 0),
(7641311, 1240732, 96574, '<td valign="top">Definitely my favorite in this challenge, I liked how the steps let you into the shot. Congrats on the blue Wendy.</td>', 'Definitely my favorite in this challenge, I liked how the steps let you into the shot. Congrats on the blue Wendy.', '2019-09-13 03:16:51.000000', NULL, 0),
(7641316, 1240704, 67145, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Venser:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roz:</b></div><hr/><i> congratulations on the red .. this is an absolutely amazing image ..  i cant imagine how you do this sort of photography .. blown me away .. :) </i></td></tr></table> <br/> <br/>It''s easy. Water + sugar + soap + glycerine + flash. You just have to make sure the plane of the soap is relatively flat and the flash is pointing in the right direction. After that it''s a liberal use of editing. </i></td></tr></table> <br/> <br/>thankyou Chris :)</td>', 'Originally posted by Venser: Originally posted by roz: congratulations on the red .. this is an absolutely amazing image ..  i cant imagine how you do this sort of photography .. blown me away .. :)   It''s easy. Water + sugar + soap + glycerine + flash. You just have to make sure the plane of the soap is relatively flat and the flash is pointing in the right direction. After that it''s a liberal use of editing.   thankyou Chris :)', '2019-09-13 06:13:02.000000', NULL, 0),
(7641319, 1240758, 30049, '<td valign="top">My Top Pick ... lovely image and met the challenge perfectly.  Should have at least made the front page.  :-}</td>', 'My Top Pick ... lovely image and met the challenge perfectly.  Should have at least made the front page.  :-}', '2019-09-13 09:22:16.000000', NULL, 0),
