(7641322, 1240700, 181505, '<td valign="top">Great job on your HM!!</td>', 'Great job on your HM!!', '2019-09-13 10:25:46.000000', NULL, 0),
(7641323, 1240759, 138630, '<td valign="top">Well seen abstract with great colors.  Congrats on the score and top ten.</td>', 'Well seen abstract with great colors.  Congrats on the score and top ten.', '2019-09-13 10:32:16.000000', NULL, 0),
(7641331, 1240732, 173844, '<td valign="top">Congratulations on the blue.  A silky image with beautiful colors, subtle textures and sculpturing, a natural bi-color.  Love the blush of sun on the sand.  A lovely shoreline study.<br/>Personal favorite of the challenge.</td>', 'Congratulations on the blue.  A silky image with beautiful colors, subtle textures and sculpturing, a natural bi-color.  Love the blush of sun on the sand.  A lovely shoreline study.Personal favorite of the challenge.', '2019-09-13 12:39:02.000000', NULL, 0),
(7641336, 1240704, 19825, '<td valign="top">Heres a nice welcome back. Fascinating image. Nicely done.</td>', 'Heres a nice welcome back. Fascinating image. Nicely done.', '2019-09-13 13:20:41.000000', NULL, 0),
(7641337, 1240732, 19825, '<td valign="top">Wonderful use of light and texture.</td>', 'Wonderful use of light and texture.', '2019-09-13 13:22:06.000000', NULL, 0),
(7641408, 1240687, 50695, '<td valign="top">I gave this a 7 because I really admire how you caught the cobwebs. I find it so difficult to get a good capture of webs.</td>', 'I gave this a 7 because I really admire how you caught the cobwebs. I find it so difficult to get a good capture of webs.', '2019-09-14 10:19:04.000000', NULL, 0),
(7641409, 1240296, 50695, '<td valign="top">this was a 7 from me. You framed this perfectly.</td>', 'this was a 7 from me. You framed this perfectly.', '2019-09-14 10:19:41.000000', NULL, 0),
(7641410, 1240718, 50695, '<td valign="top">I love how you framed this so there is no context. The depth of the ship becomes disorienting.</td>', 'I love how you framed this so there is no context. The depth of the ship becomes disorienting.', '2019-09-14 10:20:35.000000', NULL, 0),
(7641411, 1240702, 50695, '<td valign="top">I was one of your 7s. I would have bumped it higher if I''d remembered. It''s all about surfaces, thanks to your inspired crop.</td>', 'I was one of your 7s. I would have bumped it higher if I''d remembered. It''s all about surfaces, thanks to your inspired crop.', '2019-09-14 10:22:42.000000', NULL, 0),
(7641412, 1240741, 50695, '<td valign="top">not generally a fan of photos of statues, but juxtaposing it against the blurred background was a great choice. Well done.</td>', 'not generally a fan of photos of statues, but juxtaposing it against the blurred background was a great choice. Well done.', '2019-09-14 10:24:10.000000', NULL, 0),
(7641413, 1240761, 50695, '<td valign="top">forgot to bump this up from 7. delirious, disorienting, everything I want from my amusement park rides but without the stomach issues</td>', 'forgot to bump this up from 7. delirious, disorienting, everything I want from my amusement park rides but without the stomach issues', '2019-09-14 10:25:30.000000', NULL, 0),
(7641414, 1240717, 50695, '<td valign="top">I eventually realized the ocean was aluminum foil and was delighted. I love a good lo-fi illusion. it was a 7 from me and I would have bumped it higher if I remembered.</td>', 'I eventually realized the ocean was aluminum foil and was delighted. I love a good lo-fi illusion. it was a 7 from me and I would have bumped it higher if I remembered.', '2019-09-14 10:29:15.000000', NULL, 0),
(7641415, 1240757, 50695, '<td valign="top">the obscurity of this image just makes it more immersive. I imagine drowning is also a very obscure process</td>', 'the obscurity of this image just makes it more immersive. I imagine drowning is also a very obscure process', '2019-09-14 10:30:48.000000', NULL, 0),
(7641416, 1240751, 50695, '<td valign="top">this shot really fascinated and intrigued me. I couldn''t figure out the scale. I was your 7 and would have bumped it higher had I returned to the challenge.</td>', 'this shot really fascinated and intrigued me. I couldn''t figure out the scale. I was your 7 and would have bumped it higher had I returned to the challenge.', '2019-09-14 10:32:54.000000', NULL, 0),
