(7641785, 1240225, 63398, '<td valign="top">Superb find and composition.</td>', 'Superb find and composition.', '2019-09-18 17:39:04.000000', NULL, 0),
(7647667, 1240690, 100831, '<td valign="top">I don''t know how I missed this one but it does make me smile. You have a great eye and sense of imagination. I am surprised that paint comes in this color, but I like it (at least this use of it).</td>', 'I don''t know how I missed this one but it does make me smile. You have a great eye and sense of imagination. I am surprised that paint comes in this color, but I like it (at least this use of it).', '2019-12-02 09:08:33.000000', NULL, 0),
